function scheduleFieldErrors(v){const errors=[];if(v.examDate&&!validDate(v.examDate)||v.examDate&&v.startDate&&v.examDate<v.startDate)errors.push('Дата экзамена должна быть не раньше начала курса.');if(v.platformURL&&(!validURL(v.platformURL)||v.platformURL.length>2048||new URL(v.platformURL).username||new URL(v.platformURL).password))errors.push('Ссылка на платформу: укажите адрес http(s) без логина и пароля.');if(v.studyWeekdays!==undefined&&(!Array.isArray(v.studyWeekdays)||new Set(v.studyWeekdays).size!==v.studyWeekdays.length||v.studyWeekdays.some(x=>!Number.isInteger(x)||x<1||x>7)))errors.push('Некорректные дни занятий.');return errors}
function studyDaysEditor(root,values=[]){const box=el('fieldset','study-days');box.append(el('legend','','Когда хотите заниматься?'));['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].forEach((name,i)=>{const label=el('label'),input=el('input');input.type='checkbox';input.className='study-day';input.value=i+1;input.checked=values.includes(i+1);input.setAttribute('aria-label',name);label.append(input,el('span','',name));box.append(label)});root.append(box);return box}
