 Object.assign(course,{startDate:v.startDate||'',deadlineLocal:v.deadlineLocal||'',examDate:v.examDate||'',platformURL:v.platformURL||'',studyWeekdays:[...(v.studyWeekdays||[])],updatedAt:now()});const stamp=now();v.modules.forEach((m,index)=>{const old=next.topics.find(x=>x.id===m.id),record={...old,id:m.id,courseId,name:m.name.trim(),description:old?.description||'',order:index,startDate:m.startDate||'',deadlineLocal:m.deadlineLocal||'',plannedLessonCount:Number(m.plannedLessonCount),createdAt:old?.createdAt||stamp,updatedAt:stamp,archivedAt:old?.archivedAt||null,completionMode:old?.completionMode||'manual'};if(old)Object.assign(old,record);else next.topics.push(record)});
