function programFormValues(){const root=$('#editorFields'),value=name=>root.querySelector('[name='+name+']')?.value.trim()||'';return {startDate:value('programStart'),deadlineLocal:value('programDeadline'),examDate:value('programExam'),platformURL:value('programPlatform'),studyWeekdays:[...root.querySelectorAll('.study-day:checked')].map(n=>Number(n.value)),modules:[...root.querySelectorAll('.program-row')].map(row=>({id:row.dataset.id,name:row.querySelector('.program-name').value.trim(),startDate:row.querySelector('.program-start').value,deadlineLocal:row.querySelector('.program-deadline').value,plannedLessonCount:row.querySelector('.program-count').value}))}}
