function suggestedModuleStart(m){const c=state.courses.find(x=>x.id===m.courseId),days=c?.studyWeekdays||[];if(!days.length)return null;const today=day(new Date()),from=[today,m.startDate,c?.startDate].filter(Boolean).sort().at(-1),until=[m.deadlineLocal,c?.deadlineLocal,c?.examDate].filter(Boolean).sort()[0]||addCivilDays(from,365),used=new Set(state.sessions.filter(x=>x.topicId===m.id&&!x.recurrenceId).map(x=>x.startLocal.slice(0,10)));for(let date=from;date<=until&&civilDayIndex(date)-civilDayIndex(from)<=730;date=addCivilDays(date,1)){const d=new Date(date+'T12:00');if(days.includes((d.getDay()+6)%7+1)&&!used.has(date))return date+'T09:00'}return null}

