function openCourseMove(id){if(!flushInlineNotes())return;if(draft?.dirty){notify('Сначала сохраните черновик');return}const c=by('course',id);if(!c||archived('course',c))return;confirmAction('Перенести курс','Выберите направление. Все модули, лекции, конспекты, задания и отметки сохранятся.',()=>{const selected=select.value;if(commit(s=>{relocateCourse(s,id,selected)})){selectedCourse=id;selectedModule=null;section='learning';render();notify('Курс перенесён вместе со всеми материалами.')}});const current=by('subject',c.subjectId)?.directionId,select=choice($('#confirmText'),'moveDirection','Новое направление',state.directions.filter(d=>!d.archivedAt).map(d=>[d.id,d.name]),current)}
