function validateAdditionalDeadlines(s){const ids=new Set(allIds(s).concat(s.topics.flatMap(m=>(m.lectures||[]).map(l=>l.id))));for(const x of [...s.courses,...s.topics]){if(x.deadlines===undefined)continue;if(!Array.isArray(x.deadlines)||x.deadlines.length>100)throw Error('Дополнительных дедлайнов может быть не больше 100');for(const d of x.deadlines){if(!d||typeof d.id!=='string'||!d.id||d.id.length>200||ids.has(d.id))throw Error('Некорректный идентификатор дедлайна');ids.add(d.id);if(typeof d.title!=='string'||!d.title.trim()||d.title.length>300||!validDate(d.date)||d.completedAt!=null&&!Number.isFinite(Date.parse(d.completedAt)))throw Error('Для дедлайна укажите задачу и дату')}}}
