function additionalDeadlineEditor(root,x){const box=el('section','additional-deadline-editor');box.append(el('h3','','Дополнительные дедлайны'),el('p','muted','Необязательно: укажите дату и что нужно сделать. Сроки не завершают модуль автоматически.'));const list=el('div','additional-deadline-list');function row(d={}){const r=el('div','additional-deadline-row');r.dataset.id=d.id||uid();r.dataset.completedAt=d.completedAt||'';const title=field(r,'','Что нужно сделать *','text',d.title||'',300),date=field(r,'','Дата дополнительного дедлайна *','date',d.date||'');title.removeAttribute('name');date.removeAttribute('name');title.className='deadline-title';date.className='deadline-date';const label=el('label','module-check'),done=el('input');done.type='checkbox';done.className='deadline-done';done.checked=!!d.completedAt;label.append(done,el('span','','Выполнено'));r.append(label,button('Убрать дедлайн',()=>{r.remove();changed()}));r.querySelectorAll('input').forEach(n=>{n.addEventListener('input',changed);n.addEventListener('change',changed)});list.append(r);return r}for(const d of x.deadlines||[])row(d);box.append(list,button('+ Дополнительный дедлайн',()=>{if(list.childElementCount>=100){notify('Не больше 100 дополнительных дедлайнов');return}const r=row();changed();r.querySelector('input').focus()}));root.append(box)}
