function courseAgenda(s,from,until,includeOverdue=true){const result=[],plans=new Map();function add(kind,x,date,title,done=false,deadlineId=null){if(!date||done||date>until||!includeOverdue&&date<from||archivedIn(s,kind,x))return;const courseId=kind==='course'?x.id:x.courseId||s.topics.find(m=>m.id===x.topicId)?.courseId,c=s.courses.find(c=>c.id===courseId);if(!c)return;if(!plans.has(c.id))plans.set(c.id,coursePlan(s,c.id).progress);if(plans.get(c.id)===100)return;result.push({kind,id:x.id,courseId,moduleId:kind==='topic'?x.id:null,date,title,courseName:c.name,deadlineId,overdue:date<from})}for(const c of s.courses){add('course',c,c.deadlineLocal,'Основной дедлайн курса');add('course',c,c.examDate,'Экзамен');for(const d of c.deadlines||[])add('course',c,d.date,d.title,!!d.completedAt,d.id)}for(const m of s.topics){add('topic',m,m.deadlineLocal,'Срок модуля: '+m.name,!!m.completedAt);for(const d of m.deadlines||[])add('topic',m,d.date,d.title,!!d.completedAt,d.id)}for(const h of s.homeworks)add('homework',h,h.deadlineLocal,'Задание: '+h.title,progress(h)===100);return result.sort((a,b)=>a.date.localeCompare(b.date)||a.title.localeCompare(b.title))}
function archivedIn(s,kind,x){if(x.archivedAt)return true;if(kind==='course'){const sub=s.subjects.find(y=>y.id===x.subjectId);return !sub||sub.archivedAt||s.directions.find(d=>d.id===sub.directionId)?.archivedAt}const m=kind==='topic'?x:s.topics.find(m=>m.id===x.topicId),c=m&&s.courses.find(c=>c.id===m.courseId);return !m||m.archivedAt||!c||archivedIn(s,'course',c)}
function renderActiveCourses(p){const today=day(new Date()),until=addCivilDays(today,13),section=el('section','active-courses');section.append(el('h2','','Активные курсы'));const courses=state.courses.filter(c=>!archived('course',c)&&coursePlan(state,c.id).progress!==100).sort((a,b)=>(a.deadlineLocal||'9999').localeCompare(b.deadlineLocal||'9999'));for(const c of courses){const card=el('article','card active-course');card.dataset.courseId=c.id;courseDirectionHeading(card,c);card.append(el('h3','',c.name),el('p','',scheduleText(c)),el('p','muted','Дни занятий: '+studyDaysText(c.studyWeekdays||[])));if(c.startDate&&c.startDate>today)card.append(el('p','muted','Обучение ещё не началось'));if(c.deadlineLocal&&c.deadlineLocal<today)card.append(el('p','overdue','Основной дедлайн прошёл'));planProgress(card,coursePlan(state,c.id));card.append(button('Открыть курс',()=>setCourseView(c.id),'primary'),button('Изменить сроки курса',()=>openEditor('course',c.id)));section.append(card)}if(!courses.length)section.append(el('p','muted','Активных курсов пока нет.'));p.append(section);const agenda=el('section','card course-agenda');agenda.append(el('h2','','Ближайшее расписание курсов'),el('p','muted','Занятия и внутренние сроки на 14 дней, а также невыполненные просроченные дедлайны. Дни недели — ваши предпочтения; даты занятий заполняются в модулях.'));const end=new Date(until+'T23:59:59'),start=new Date(today+'T00:00:00'),events=sessionsInRange(start,end).filter(x=>x.status!=='completed'&&courses.some(c=>state.topics.some(m=>m.id===x.topicId&&m.courseId===c.id))),items=courseAgenda(state,today,until).concat(events.map(x=>({kind:'session',id:x.id,date:x.startLocal.slice(0,10),time:x.startLocal.slice(11),title:x.title,courseName:state.courses.find(c=>state.topics.some(m=>m.id===x.topicId&&m.courseId===c.id))?.name}))).sort((a,b)=>a.date.localeCompare(b.date)||(a.time||'').localeCompare(b.time||''));for(const item of items){const b=button((item.overdue?'Просрочено · ':'')+item.date+(item.time?' '+item.time:'')+' · '+item.courseName+' · '+item.title,()=>{if(item.kind==='session'||item.kind==='homework')openEditor(item.kind,item.id);else setCourseView(item.courseId,item.moduleId)},item.overdue?'overdue':'');b.dataset.agendaDate=item.date;agenda.append(b)}if(!items.length)agenda.append(el('p','muted','В ближайшие 14 дней занятий и дедлайнов нет. Добавьте даты в курс или модуль.'));agenda.append(button('Весь календарь',()=>setSection('calendar')));p.append(agenda)}

$('#editorForm').addEventListener('submit',e=>{e.preventDefault();saveEditor()});$('#closeEditor').addEventListener('click',()=>closeEditor());$('#cancelEditor').addEventListener('click',()=>closeEditor());$('#scrim').addEventListener('click',()=>closeEditor());document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#editor').hidden&&!$('#confirmDialog').open){e.preventDefault();closeEditor()}});$('#addGlobal').addEventListener('click',()=>{const c=el('div','card'),p=$('#main');c.append(el('h3','','Что добавить?'));for(const k of ['direction','subject','course','topic','session','homework','goal'])c.append(button(TITLES[k],()=>{c.remove();openEditor(k)}));p.prepend(c)});$('#menuToggle').addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'));$('#importFile').addEventListener('change',e=>{importData(e.target.files[0]);e.target.value=''});window.addEventListener('storage',e=>{if(e.key===KEY||e.key===null){blocked=true;status('Конфликт вкладок');let external;try{external=JSON.parse(e.newValue)}catch{}notify((external?.timerState?.status&&external.timerState.status!=='idle'?'Таймер уже работает в другой вкладке. ':'')+'Данные обновлены в другой вкладке. Перезагрузите страницу, чтобы продолжить.');renderTimer()}});
window.addEventListener('beforeunload',e=>{if(draft?.dirty||inlineNoteDrafts.size){e.preventDefault();e.returnValue=''}});
$('#editor').addEventListener('keydown',e=>{if(e.key!=='Tab')return;const fields=[...$('#editor').querySelectorAll('button,input,select,textarea,a')].filter(x=>!x.disabled&&x.getClientRects().length);const first=fields[0],last=fields.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
